(2045,	223,	'content_sections_0_section_heading',	'Cancun Airport  Private Terminal FBO'),
(2046,	223,	'_content_sections_0_section_heading',	'field_6a467853f47df'),
(2047,	223,	'content_sections_0_section_content',	'<h2 class=\"PDq2pG_selectionAnchorContainer\" data-section-id=\"5veygf\" data-start=\"793\" data-end=\"827\"><span style=\"color: #00467b;\">What is the Cancun Airport FBO?</span></h2>\r\n<p data-start=\"829\" data-end=\"1058\">The Cancun Airport <a href=\"https://share.google/22a4sLJrdXfn2HY5P\">FBO (Fixed Base Operator)</a> is the private aviation terminal at Cancun International Airport. Unlike the commercial terminals (T2, T3 and T4), the FBO is exclusively used for private aircraft and charter flights.</p>\r\n<p data-start=\"1060\" data-end=\"1304\">Flights Holbox operates all private flights to Holbox from this terminal, providing a fast, comfortable and exclusive travel experience. Passengers avoid the busy commercial terminals and enjoy a private check-in before boarding their aircraft.</p>\r\n<p data-start=\"1306\" data-end=\"1421\">The flight from Cancun to Holbox takes approximately <strong data-start=\"1359\" data-end=\"1373\">30 minutes</strong>, making it the fastest way to reach the island.</p>'),
(2048,	223,	'_content_sections_0_section_content',	'field_6a46785cf47e0'),
(2049,	223,	'content_sections_1_section_heading',	'Location Private Terminal Cancun FBO'),
(2050,	223,	'_content_sections_1_section_heading',	'field_6a467853f47df'),
(2051,	223,	'content_sections_1_section_content',	'&nbsp;\r\n<h2 class=\"PDq2pG_selectionAnchorContainer\" data-section-id=\"5veygf\" data-start=\"793\" data-end=\"827\"><span style=\"color: #00467b;\">Where is the private terminal in Cancun located?</span></h2>\r\n<ul>\r\n 	<li>Located inside Cancun International Airport</li>\r\n 	<li data-section-id=\"47lfql\" data-start=\"1527\" data-end=\"1562\">Separate from Terminal 2, 3 and 4</li>\r\n 	<li data-section-id=\"7tmiah\" data-start=\"1563\" data-end=\"1588\">Only accessible by road</li>\r\n 	<li data-section-id=\"1qu0oce\" data-start=\"1589\" data-end=\"1624\">Taxi or private transfer required</li>\r\n 	<li data-section-id=\"1w9l0ny\" data-start=\"1625\" data-end=\"1651\">Not connected by shuttle</li>\r\n 	<li data-section-id=\"1w9l0ny\" data-start=\"1625\" data-end=\"1651\"><strong>Find the exact Location on google maps <a href=\"https://share.google/22a4sLJrdXfn2HY5P\">here</a></strong></li>\r\n</ul>'),
(2052,	223,	'_content_sections_1_section_content',	'field_6a46785cf47e0'),
(2053,	223,	'content_sections_2_section_heading',	'How To Get To The Private Terminal in Cancun'),
(2054,	223,	'_content_sections_2_section_heading',	'field_6a467853f47df'),
(2055,	223,	'content_sections_2_section_content',	'<h2 class=\"PDq2pG_selectionAnchorContainer\" data-section-id=\"5veygf\" data-start=\"793\" data-end=\"827\"><span style=\"color: #00467b;\">How do i get to the private Terminal in Cancun?</span></h2>\r\n<h3>From Cancun international Airport, Terminal 2, 3 and 4</h3>\r\n<p data-start=\"1868\" data-end=\"1903\">If arriving on a commercial flight:</p>\r\n\r\n<ul data-start=\"1905\" data-end=\"2030\">\r\n 	<li data-section-id=\"7po1z1\" data-start=\"1905\" data-end=\"1925\">Exit your terminal</li>\r\n 	<li data-section-id=\"1rw1hg5\" data-start=\"1926\" data-end=\"1959\">Take an authorised airport taxi, we can help you setting up your transfer</li>\r\n 	<li data-section-id=\"1djyukp\" data-start=\"1960\" data-end=\"1998\">Taxi ride approximately 5–10 minutes</li>\r\n 	<li data-section-id=\"lnzntz\" data-start=\"1999\" data-end=\"2030\">Cost approximately <strong data-start=\"2020\" data-end=\"2030\">30 USD</strong></li>\r\n 	<li data-section-id=\"lnzntz\" data-start=\"1999\" data-end=\"2030\">you can not walk between the international terminal and the private terminal</li>\r\n</ul>\r\n<h3>From Cancun Center or any other location</h3>\r\n<ul>\r\n 	<li>Take an authorised  taxi, we can help you setting up your transfer</li>\r\n 	<li>contact<span style=\"color: #e6af2a;\"><a style=\"color: #e6af2a;\" href=\"https://goholboxtransfers.com/\"> Go Holbox Transfers</a> </span>for a safe transfer service</li>\r\n</ul>\r\n<h3>Airport Fee</h3>\r\n<strong data-start=\"471\" data-end=\"497\">Airport Use Fee (TUA):</strong> Passengers departing on domestic private charter flights from the <strong data-start=\"564\" data-end=\"600\">Cancun FBO (Fixed Base Operator)</strong> are required to pay an <strong data-start=\"624\" data-end=\"675\">Airport Use Fee (TUA) of MXN $200 per passenger</strong>. This fee is <strong data-start=\"689\" data-end=\"705\">not included</strong> in the charter price and is payable before departure.\r\n\r\n&nbsp;'),
(2056,	223,	'_content_sections_2_section_content',	'field_6a46785cf47e0'),
