(350,	0,	'2026-07-08 22:00:46',	'2026-07-08 21:00:46',	'<!-- wp:acf/support-panel {\"name\":\"acf/support-panel\",\"data\":{\"heading\":\"Support Centre\",\"_heading\":\"field_temp_sp_heading\",\"intro\":\"Find answers to common questions, grouped by topic.\",\"_intro\":\"field_temp_sp_intro\",\"topics\":[{\"topic_name\":\"Booking\",\"_topic_name\":\"field_temp_sp_topic_name\",\"topic_intro\":\"Everything about making a reservation.\",\"_topic_intro\":\"field_temp_sp_topic_intro\",\"faqs\":[{\"question\":\"How do I book a flight?\",\"_question\":\"field_temp_sp_question\",\"answer\":\"\\u003cp\\u003eUse the search form on the homepage to select your route and dates.\\u003c/p\\u003e\",\"_answer\":\"field_temp_sp_answer\"},{\"question\":\"Can I book for a group?\",\"_question\":\"field_temp_sp_question\",\"answer\":\"\\u003cp\\u003eYes, groups of up to 6 passengers can be booked in a single reservation via the aircraft charter option.\\u003c/p\\u003e\",\"_answer\":\"field_temp_sp_answer\"}],\"_faqs\":\"field_temp_sp_faqs\"},{\"topic_name\":\"Payments\",\"_topic_name\":\"field_temp_sp_topic_name\",\"topic_intro\":\"How and when you pay.\",\"_topic_intro\":\"field_temp_sp_topic_intro\",\"faqs\":[{\"question\":\"What payment methods do you accept?\",\"_question\":\"field_temp_sp_question\",\"answer\":\"\\u003cp\\u003eWe accept all major credit cards and PayPal.\\u003c/p\\u003e\",\"_answer\":\"field_temp_sp_answer\"},{\"question\":\"Is a deposit required?\",\"_question\":\"field_temp_sp_question\",\"answer\":\"\\u003cp\\u003eYes, a 20% deposit secures your booking, with the balance due 48 hours before departure.\\u003c/p\\u003e\",\"_answer\":\"field_temp_sp_answer\"}],\"_faqs\":\"field_temp_sp_faqs\"},{\"topic_name\":\"Cancellations\",\"_topic_name\":\"field_temp_sp_topic_name\",\"topic_intro\":\"Changing or cancelling your trip.\",\"_topic_intro\":\"field_temp_sp_topic_intro\",\"faqs\":[{\"question\":\"Can I get a refund?\",\"_question\":\"field_temp_sp_question\",\"answ